        rejectUnauthorized: true,
        headers: {
          'Content-Type': 'application/json',
          PROXY_USER: ADMIN_USER,
          PROXY_ROLE: PROXY_ADMIN_ROLE,
        },
      })
      .then((value) => {
        Promise.resolve(value);
      })
      .catch((value) => {
        Promise.resolve(value);
      });
  });
});

